 20	export interface Preparation {
 21	    plainText?: string;
 22	    document?: Element;
 23	    showEmbeddedImages?: boolean;
 24	    showRemoteImages?: boolean;
 25	    hasRemoteImages?: boolean;
 26	    hasEmbeddedImages?: boolean;
 27	    remoteImages?: MessageImage[];
 28	    embeddedImages?: MessageImage[];
 29	}
