 31	export const prepareHtml = async (
 32	    message: MessageState,
 33	    base64Cache: Base64Cache,
 34	    mailSettings: MailSettings | undefined,
 35	    onLoadEmbeddedImages: (attachments: Attachment[]) => Promise<LoadEmbeddedResults>,
 36	    onLoadRemoteImagesProxy: (imagesToLoad: MessageRemoteImage[]) => void,
 37	    onLoadFakeImagesProxy: (imagesToLoad: MessageRemoteImage[], firstLoad?: boolean) => void,
 38	    onLoadRemoteImagesDirect: (imagesToLoad: MessageRemoteImage[]) => void
 39	): Promise<Preparation> => {
 40	    const document = transformEscape(message.decryption?.decryptedBody, base64Cache);
 41	
 42	    transformBase(document);
 43	
 44	    transformLinks(document);
 45	
 46	    const { showEmbeddedImages, hasEmbeddedImages, embeddedImages } = await transformEmbedded(
 47	        { ...message, messageDocument: { document } },
 48	        mailSettings,
 49	        onLoadEmbeddedImages
 50	    );
 51	
 52	    transformWelcome(document);
 53	
 54	    transformStylesheet(document);
 55	
 56	    const { showRemoteImages, hasRemoteImages, remoteImages } = transformRemote(
 57	        { ...message, messageDocument: { document } },
 58	        mailSettings,
